import { join } from 'node:path';
import SwaggerParser = require('@apidevtools/swagger-parser');
import Ajv, { ValidateFunction } from 'ajv';
import addFormats from 'ajv-formats';

/** Our contract v2, the one we hand to Booking (generated by scripts/build-contract-v2.js). */
export const CONTRACT_V2_FILE = join(__dirname, '..', '..', '..', '..', 'contracts', 'vuelos-openapi-v2-ram-alliance.yaml');

interface Operation {
  operationId?: string;
  responses?: Record<string, { content?: Record<string, { schema?: object }> }>;
}
interface Contract {
  paths: Record<string, Record<string, Operation>>;
}

/**
 * Checks real answers of the running API against the response schemas of the contract: the way to keep the document
 * honest. `$ref`s are resolved first; `nullable` is understood natively by Ajv.
 */
export class ContractV2Validator {
  private readonly ajv = addFormats(new Ajv({ strict: false, allErrors: true }));
  private readonly compiled = new Map<string, ValidateFunction>();

  private constructor(private readonly contract: Contract) {}

  static async load(): Promise<ContractV2Validator> {
    const contract = (await SwaggerParser.dereference(CONTRACT_V2_FILE)) as unknown as Contract;
    dropWriteOnlyFromRequired(contract, new Set());
    return new ContractV2Validator(contract);
  }

  /** The schema of `method path -> status` for the content type of the answer, or throws if the contract does not describe it. */
  private schemaOf(method: string, path: string, status: number, contentType: string): object {
    const operation = this.contract.paths[path]?.[method.toLowerCase()];
    if (!operation) throw new Error(`The contract has no operation ${method.toUpperCase()} ${path}`);
    const response = operation.responses?.[String(status)];
    if (!response) throw new Error(`The contract does not declare a ${status} answer for ${method.toUpperCase()} ${path} (it declares ${Object.keys(operation.responses ?? {}).join(', ')})`);
    const content = response.content ?? {};
    const media = Object.keys(content).find((type) => contentType.startsWith(type)) ?? Object.keys(content)[0];
    const schema = media ? content[media]?.schema : undefined;
    if (!schema) throw new Error(`The ${status} answer of ${method.toUpperCase()} ${path} has no schema`);
    return schema;
  }

  /** Throws a readable message listing every mismatch. `contentType` is the answer's `Content-Type` header. */
  check(method: string, path: string, status: number, body: unknown, contentType = 'application/json'): void {
    const key = `${method} ${path} ${status} ${contentType}`;
    let validate = this.compiled.get(key);
    if (!validate) {
      validate = this.ajv.compile(this.schemaOf(method, path, status, contentType));
      this.compiled.set(key, validate);
    }
    if (!validate(body)) {
      const errors = (validate.errors ?? []).map((e) => `${e.instancePath || '/'} ${e.message}`).join('; ');
      throw new Error(`${method.toUpperCase()} ${path} ${status} does not match the contract: ${errors}\nBody: ${JSON.stringify(body).slice(0, 600)}`);
    }
  }
}

/**
 * OpenAPI: a `writeOnly` property (a webhook's `secret`) is sent by the client and never returned, so it cannot be
 * required in an answer. Ajv does not know it, so it is taken out of `required` before the schemas are compiled.
 */
function dropWriteOnlyFromRequired(node: unknown, seen: Set<unknown>): void {
  if (node === null || typeof node !== 'object' || seen.has(node)) return;
  seen.add(node);
  const schema = node as { required?: string[]; properties?: Record<string, { writeOnly?: boolean }> };
  if (Array.isArray(schema.required) && schema.properties) {
    schema.required = schema.required.filter((name) => !schema.properties?.[name]?.writeOnly);
  }
  for (const child of Object.values(node)) dropWriteOnlyFromRequired(child, seen);
}
